Definition chk_cost (m : Z) : bool :=
  Z.max (acostS (stc_m m)) (acostS (stc_m m + 1)) <=? Z.max 8448 (32 * m + 8294).

Lemma chk_costs : forallb chk_cost (MallocLayout.Zseq 0 (Z.to_nat 8191)) = true.
Proof.
ltac2:(KReplay.run1 (kr_t_MallocCredit ()) [] "p;2p;1p;3g0000j27Tg000Jj13Tg000hj12Tg001Hj26Tg002Nj35Tg002jj34Tg003Dj11Tf0#1#1p=0g003iR0g004IR1'7g004ig005Gg006Qg006o#0#0#0#0#0#0#3#2'635=401do"). Qed.

