Section WithLayout.
Context {ML : MallocLayout} {MLok : MallocLayoutOk ML}.
Local Notation u := bv_unsigned (only parsing).

Definition g_roomP (A : astate) (h : VmMaps) (k p : Z) : Prop :=
  g_room A h k 0 /\ p <= (ROOM_BCAP - vm_backed_bytes h) + pot2 A.

